The original visits the whole graph instead of selecting the target’s ancestors, ignores missing references, and treats cycles as already visited. DFS order also does not guarantee the lexically smallest task among all currently available tasks.

```python
import heapq


def plan(tasks, target):
    if target not in tasks:
        raise ValueError(f"Unknown target: {target}")

    # Validate the entire graph, including disconnected components.
    dependents = {name: set() for name in tasks}
    prerequisites = {}
    for name, deps in tasks.items():
        prerequisites[name] = set(deps)
        for dep in prerequisites[name]:
            if dep not in tasks:
                raise ValueError(f"Unknown prerequisite {dep} for {name}")
            dependents[dep].add(name)

    indegree = {name: len(deps) for name, deps in prerequisites.items()}
    ready = [name for name, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    visited = 0
    while ready:
        name = heapq.heappop(ready)
        visited += 1
        for child in dependents[name]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)
    if visited != len(tasks):
        raise ValueError("Dependency cycle")

    needed = set()
    pending = [target]
    while pending:
        name = pending.pop()
        if name not in needed:
            needed.add(name)
            pending.extend(prerequisites[name])

    indegree = {name: len(prerequisites[name]) for name in needed}
    ready = [name for name, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    result = []
    while ready:
        name = heapq.heappop(ready)
        result.append(name)
        for child in dependents[name] & needed:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)
    return result


if __name__ == "__main__":
    tasks = {"app": ["api", "ui"], "api": ["core"],
             "ui": ["core"], "core": []}
    print(plan(tasks, "app"))  # ['core', 'api', 'ui', 'app']
```

`core` is initially available. After it runs, `api` and `ui` become available; the heap selects `api` first, then `ui`, then `app`. The heap makes each choice lexical regardless of dictionary, dependency-list, or set iteration order.

The current implementation rejects this graph because it validates the disconnected cycle, even though the plan for `app` is valid:

```python
{'app': ['core'], 'core': [], 'x': ['y'], 'y': ['x']}
```

The revised function examines only the target's prerequisite closure. A heap selects the smallest available task, and sets treat repeated prerequisites as one dependency.

```python
import heapq


def plan(tasks, target):
    if target not in tasks:
        raise ValueError(f'Unknown target: {target}')

    needed = set()
    pending = [target]
    prerequisites = {}
    while pending:
        name = pending.pop()
        if name in needed:
            continue
        needed.add(name)
        deps = set(tasks[name])
        for dep in deps:
            if dep not in tasks:
                raise ValueError(f'Unknown prerequisite {dep} for {name}')
        prerequisites[name] = deps
        pending.extend(deps)

    dependents = {name: set() for name in needed}
    indegree = {name: len(prerequisites[name]) for name in needed}
    for name, deps in prerequisites.items():
        for dep in deps:
            dependents[dep].add(name)

    ready = [name for name in needed if indegree[name] == 0]
    heapq.heapify(ready)
    result = []
    while ready:
        name = heapq.heappop(ready)
        result.append(name)
        for child in dependents[name]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)
    if len(result) != len(needed):
        raise ValueError('Dependency cycle')
    return result


def raises(fn):
    try:
        fn()
    except ValueError:
        return
    raise AssertionError('expected ValueError')


if __name__ == '__main__':
    diamond = {'app': ['api', 'ui'], 'api': ['core'],
               'ui': ['core'], 'core': []}
    assert plan(diamond, 'app') == ['core', 'api', 'ui', 'app']
    assert plan({'app': ['core'], 'core': [],
                 'x': ['y'], 'y': ['x']}, 'app') == ['core', 'app']
    raises(lambda: plan({'a': ['b'], 'b': ['a']}, 'a'))
    raises(lambda: plan({'a': ['missing']}, 'a'))
    assert plan({'a': ['b', 'b'], 'b': []}, 'a') == ['b', 'a']
```

Both operations leave both stacks unchanged: an out-of-bounds deletion raises `ValueError` before recording anything; inserting `''` returns without recording anything. Invalid cursor moves raise `TypeError` for a non-integer or `ValueError` for an out-of-range position, with all state unchanged. Empty undo and redo return `False`.

```python
class Buffer:
    LIMIT = 4

    def __init__(self, text=''):
        if not isinstance(text, str):
            raise TypeError('text must be a string')
        self.text, self.cursor = text, len(text)
        self.undo_stack, self.redo_stack = [], []

    def _push_undo(self):
        self.undo_stack.append((self.text, self.cursor))
        if len(self.undo_stack) > self.LIMIT:
            del self.undo_stack[0]

    def move(self, position):
        if type(position) is not int:
            raise TypeError('position must be an integer')
        if not 0 <= position <= len(self.text):
            raise ValueError('cursor out of bounds')
        self.cursor = position

    def insert(self, s):
        if not isinstance(s, str):
            raise TypeError('insertion must be a string')
        if not s:
            return
        self._push_undo()
        self.redo_stack.clear()
        p = self.cursor
        self.text = self.text[:p] + s + self.text[p:]
        self.cursor = p + len(s)

    def delete(self, count):
        if type(count) is not int:
            raise TypeError('count must be an integer')
        if count < 0 or count > len(self.text) - self.cursor:
            raise ValueError('deletion out of bounds')
        if not count:
            return
        self._push_undo()
        self.redo_stack.clear()
        p = self.cursor
        self.text = self.text[:p] + self.text[p + count:]

    def undo(self):
        if not self.undo_stack:
            return False
        self.redo_stack.append((self.text, self.cursor))
        self.text, self.cursor = self.undo_stack.pop()
        return True

    def redo(self):
        if not self.redo_stack:
            return False
        self._push_undo()
        self.text, self.cursor = self.redo_stack.pop()
        return True


if __name__ == '__main__':
    b = Buffer()
    for c in 'abcde':
        b.insert(c)
    assert len(b.undo_stack) == 4
    for _ in range(4):
        assert b.undo()
    assert (b.text, b.cursor) == ('a', 1) and not b.undo()

    b = Buffer('a🙂b')
    b.move(1)
    b.delete(1)
    assert (b.text, b.cursor) == ('ab', 1)
    b.move(2)
    assert b.undo() and (b.text, b.cursor) == ('a🙂b', 1)
    assert b.redo() and (b.text, b.cursor) == ('ab', 2)
    assert b.undo()
    b.insert('X')
    assert (b.text, b.cursor) == ('aX🙂b', 2) and not b.redo()

    before = (b.text, b.cursor, b.undo_stack[:], b.redo_stack[:])
    b.insert('')
    for action in (lambda: b.delete(99), lambda: b.move(-1)):
        try:
            action()
        except ValueError:
            pass
        else:
            raise AssertionError('expected ValueError')
    assert (b.text, b.cursor, b.undo_stack, b.redo_stack) == before
```

The helper mutates its input, adds four blanks when the length is already divisible by four, and advances its indices by one instead of two, repeating some slots and omitting others. It also returns labels without indices.

For `['A', 'B', 'C', 'D', 'E']`, padding gives length 8, with blanks at indices 5–7:

- Sheet 0: front `(7, None), (0, 'A')`; back `(1, 'B'), (6, None)`.
- Sheet 1: front `(5, None), (2, 'C')`; back `(3, 'D'), (4, 'E')`.

Each copy needs two sheets, so 57 copies need 114 sheets; 166 of the 280 remain.

```python
def plan_copy(labels):
    padded = list(labels)
    padded.extend([None] * (-len(padded) % 4))
    length = len(padded)

    def slot(index):
        return (index, padded[index])

    return [
        {
            'front': (slot(length - 1 - 2*i), slot(2*i)),
            'back': (slot(2*i + 1), slot(length - 2 - 2*i)),
        }
        for i in range(length // 4)
    ]


def plan_copies(labels, copies):
    if type(copies) is not int or copies < 0:
        raise ValueError('copies must be a nonnegative integer')
    labels = list(labels)
    return [plan_copy(labels) for _ in range(copies)]


if __name__ == '__main__':
    pages = ['A', 'B', 'C', 'D', 'E']
    sheets = plan_copy(pages)
    for number, sheet in enumerate(sheets, 1):
        print(number, sheet)
    assert pages == ['A', 'B', 'C', 'D', 'E']
    indices = [index for sheet in sheets for side in ('front', 'back')
               for index, label in sheet[side]]
    assert sorted(indices) == list(range(8))
    assert len(plan_copies(pages, 57)) * len(sheets) == 114
```

An empty input produces an empty plan; duplicate labels remain distinguishable by their indices.

The original sorts axis names instead of preserving their declared order, matches exclusions only as whole dictionaries, and does not validate exclusion axes or values.

For axes `os=[linux, mac]`, `mode=[fast, safe]`, `db=[a, b]` in that order, exclusion `{'os': 'mac', 'mode': 'fast'}` removes both matching database variants. Retained rows, shown as `(os, mode, db)`, are:

```text
(linux, fast, a)  (linux, fast, b)
(linux, safe, a)  (linux, safe, b)
(mac, safe, a)    (mac, safe, b)
```

With three workers, these six cases take two 12-minute waves, or 24 minutes, assuming simultaneous starts and no overhead.

```python
from itertools import product


def expand(axes, excluded):
    # Materialize values once so validation and expansion see the same data.
    axes = {name: tuple(values) for name, values in axes.items()}
    exclusions = list(excluded)
    for rule in exclusions:
        for name, value in rule.items():
            if name not in axes:
                raise ValueError(f'Unknown axis: {name}')
            if value not in axes[name]:
                raise ValueError(f'Unknown value {value!r} for {name}')

    names = list(axes)
    rows = []
    for values in product(*(axes[name] for name in names)):
        row = dict(zip(names, values))
        if not any(all(row[name] == value for name, value in rule.items())
                   for rule in exclusions):
            rows.append(row)
    return rows


if __name__ == '__main__':
    axes = {'os': ['linux', 'mac'], 'mode': ['fast', 'safe'],
            'db': ['a', 'b']}
    rows = expand(axes, [{'os': 'mac', 'mode': 'fast'}])
    assert [tuple(r.values()) for r in rows] == [
        ('linux', 'fast', 'a'), ('linux', 'fast', 'b'),
        ('linux', 'safe', 'a'), ('linux', 'safe', 'b'),
        ('mac', 'safe', 'a'), ('mac', 'safe', 'b')]
    assert len(expand(axes, [])) == 8
    assert expand(axes, [{}]) == []
    assert expand({}, []) == [{}]
    assert expand({'x': []}, []) == []
    for rule in ({'unknown': 'a'}, {'os': 'windows'}):
        try:
            expand(axes, [rule])
        except ValueError:
            pass
        else:
            raise AssertionError('invalid exclusion accepted')
```

