The exclusion removes exactly `(linux, safe, b)` and `(mac, safe, b)`. The six remaining rows retain their original product order. Slicing happens only after validation and filtering; omitted `count` means all remaining rows.

```python
from itertools import product


def expand(axes, excluded, start=0, count=None):
    if type(start) is not int or start < 0:
        raise ValueError('start must be a nonnegative integer')
    if count is not None and (type(count) is not int or count < 0):
        raise ValueError('count must be a nonnegative integer or None')

    axes = {name: tuple(values) for name, values in axes.items()}
    rules = list(excluded)
    for rule in rules:
        for name, value in rule.items():
            if name not in axes:
                raise ValueError(f'Unknown axis: {name}')
            if value not in axes[name]:
                raise ValueError(f'Unknown value {value!r} for {name}')

    names = list(axes)
    rows = []
    for values in product(*(axes[name] for name in names)):
        row = dict(zip(names, values))
        if not any(all(row[name] == value for name, value in rule.items())
                   for rule in rules):
            rows.append(row)
    return rows[start:] if count is None else rows[start:start + count]


if __name__ == '__main__':
    axes = {'os': ['linux', 'mac'], 'mode': ['fast', 'safe'],
            'db': ['a', 'b']}
    rules = [{'mode': 'safe', 'db': 'b'}]
    rows = expand(axes, rules)
    assert [tuple(row.values()) for row in rows] == [
        ('linux', 'fast', 'a'), ('linux', 'fast', 'b'),
        ('linux', 'safe', 'a'), ('mac', 'fast', 'a'),
        ('mac', 'fast', 'b'), ('mac', 'safe', 'a')]
    assert expand(axes, rules, start=2, count=2) == rows[2:4]
    assert [tuple(r.values()) for r in expand(axes, rules, 2, 2)] == [
        ('linux', 'safe', 'a'), ('mac', 'fast', 'a')]
    assert expand(axes, rules, count=0) == []
    assert expand(axes, [{}]) == []
    assert len(expand(axes, [])) == 8

    try:
        expand(axes, [{'mod': 'safe'}], count=0)
    except ValueError as exc:
        assert str(exc) == 'Unknown axis: mod'
    else:
        raise AssertionError('typo accepted')
    for kwargs in ({'start': -1}, {'count': -1}):
        try:
            expand(axes, rules, **kwargs)
        except ValueError:
            pass
        else:
            raise AssertionError('negative slice accepted')
